import org.apache.lucene.document.Document;
import org.apache.lucene.document.SortedSetDocValuesField;
import org.apache.lucene.facet.FacetResult;
import org.apache.lucene.facet.FacetsCollectorManager;
import org.apache.lucene.facet.StringDocValuesReaderState;
import org.apache.lucene.facet.StringValueFacetCounts;
import org.apache.lucene.index.DirectoryReader;
import org.apache.lucene.index.IndexWriter;
import org.apache.lucene.index.IndexWriterConfig;
import org.apache.lucene.search.MatchAllDocsQuery;
import org.apache.lucene.search.MatchNoDocsQuery;
import org.apache.lucene.search.MultiCollectorManager;
import org.apache.lucene.store.ByteBuffersDirectory;
import org.apache.lucene.store.Directory;
import org.apache.lucene.util.BytesRef;

public class Repro {
  public static void main(String[] args) throws Exception {
    Directory dir = new ByteBuffersDirectory();
    IndexWriter writer = new IndexWriter(dir, new IndexWriterConfig());
    Document doc = new Document();
    doc.add(new SortedSetDocValuesField("field", new BytesRef("foo")));
    writer.addDocument(doc);
    writer.close();

    DirectoryReader reader = DirectoryReader.open(dir);

    // Case 1: no docs matched (the reported NPE)
    MultiCollectorManager merged =
        new MultiCollectorManager(
            new org.apache.lucene.search.TopScoreDocCollectorManager(10, 10),
            new FacetsCollectorManager());
    Object[] results = reader.search(new MatchNoDocsQuery(), merged);
    StringDocValuesReaderState state = new StringDocValuesReaderState(reader, "field");
    StringValueFacetCounts counts = new StringValueFacetCounts(state, (org.apache.lucene.facet.FacetsCollector) results[1]);
    FacetResult top = counts.getTopChildren(10, "field");
    if (top.childCount != 0 || top.labelValues.length != 0 || top.value.longValue() != 0) {
      throw new AssertionError("expected empty result, got " + top);
    }
    FacetResult all = counts.getAllChildren("field");
    if (all.labelValues.length != 0) throw new AssertionError("getAllChildren not empty");
    Object specific = counts.getSpecificValue("field", "foo");
    if (!Integer.valueOf(0).equals(((Number) specific).intValue())) {
      throw new AssertionError("getSpecificValue should be 0, got " + specific);
    }
    System.out.println("no-match OK: " + top);

    // Case 2: all docs matched (counts still work)
    Object[] results2 = reader.search(new MatchAllDocsQuery(), new FacetsCollectorManager());
    StringDocValuesReaderState state2 = new StringDocValuesReaderState(reader, "field");
    StringValueFacetCounts counts2 =
        new StringValueFacetCounts(state2, (org.apache.lucene.facet.FacetsCollector) results2[0]);
    FacetResult top2 = counts2.getTopChildren(10, "field");
    if (top2.childCount != 1
        || top2.labelValues.length != 1
        || !"foo".equals(top2.labelValues[0].label)
        || top2.labelValues[0].value.intValue() != 1) {
      throw new AssertionError("expected foo=1, got " + top2);
    }
    System.out.println("all-match OK: " + top2);

    // Case 3: count-all constructor still works
    StringValueFacetCounts counts3 = new StringValueFacetCounts(new StringDocValuesReaderState(reader, "field"));
    FacetResult top3 = counts3.getTopChildren(10, "field");
    if (top3.childCount != 1) throw new AssertionError("expected foo, got " + top3);
    System.out.println("count-all OK: " + top3);

    reader.close();
    dir.close();
    System.out.println("ALL OK");
  }
}

