        searcher.search(new MatchAllDocsQuery(), new MultiCollectorManager(new FacetsCollectorManager()));
    StringDocValuesReaderState state2 = new StringDocValuesReaderState(rawReader, "field");
    StringValueFacetCounts counts2 =
        new StringValueFacetCounts(state2, (FacetsCollector) results2[0]);
    FacetResult top2 = counts2.getTopChildren(10, "field");
    if (top2.childCount != 1
